/**
 * Load Test Benchmark Script Generator & Validation Engine (k6 & Locust)
 * Generates test scripts and compares simulated metrics vs actual measured test runs.
 */

/**
 * Generate k6 Load Test JavaScript script (script.js)
 */
export function generateK6Script(nodes = [], workload = {}, options = {}) {
  const targetRps = workload.requestsPerSecond || 1200;
  const targetVus = Math.min(Math.round(targetRps / 10), 1000);
  const targetHost = options.targetHost || 'https://api.yourdomain.com';

  return `import http from 'k6/http';
import { check, sleep } from 'k6';

// Auto-generated by InfraSaaS Load Test Generator (https://infrasaas.app)
// Target RPS: ${targetRps} req/sec | Target VUs: ${targetVus}

export const options = {
  stages: [
    { duration: '30s', target: ${Math.round(targetVus * 0.3)} }, // Ramp-up to 30% load
    { duration: '1m',  target: ${targetVus} },               // Sustained peak load (${targetRps} RPS)
    { duration: '30s', target: ${Math.round(targetVus * 1.5)} }, // 150% Stress spike test
    { duration: '30s', target: 0 },                       // Ramp-down to 0
  ],
  thresholds: {
    http_req_failed: ['rate<0.01'],    // Error rate under 1%
    http_req_duration: ['p(95)<500'],  // 95% of requests under 500ms
  },
};

export default function () {
  const url = '${targetHost}/api/v1/resource';
  const payload = JSON.stringify({
    timestamp: Date.now(),
    sampleData: 'InfraSaaS benchmark payload',
  });

  const params = {
    headers: {
      'Content-Type': 'application/json',
      'User-Agent': 'k6-InfraSaaS-Benchmark/1.0',
    },
  };

  const res = http.post(url, payload, params);

  check(res, {
    'status is 200/201': (r) => r.status === 200 || r.status === 201,
    'response latency < 500ms': (r) => r.timings.duration < 500,
  });

  sleep(0.1);
}
`;
}

/**
 * Generate Locust Python Load Test script (locustfile.py)
 */
export function generateLocustScript(nodes = [], workload = {}, options = {}) {
  const targetHost = options.targetHost || 'https://api.yourdomain.com';

  return `# Auto-generated by InfraSaaS Load Test Generator (https://infrasaas.app)
# Run command: locust -f locustfile.py --host=${targetHost}

import time
from locust import HttpUser, task, between

class InfrastructureLoadTester(HttpUser):
    wait_time = between(0.1, 0.5)

    @task(3)
    def test_main_endpoint(self):
        self.client.get("/api/v1/resource", headers={"User-Agent": "Locust-InfraSaaS"})

    @task(1)
    def test_heavy_post(self):
        payload = {
            "workload": "stress_test",
            "request_size_kb": ${workload.requestSize || 100}
        }
        self.client.post("/api/v1/process", json=payload)
`;
}

/**
 * Compare Simulated Prediction vs Real Measured Benchmark Results
 */
export function evaluateBenchmarkAccuracy(simulatedMetrics = {}, measuredData = {}) {
  const simLatency = simulatedMetrics.avgLatencyMs || 50;
  const realLatency = parseFloat(measuredData.measuredLatencyMs) || simLatency;

  const simErrorRate = simulatedMetrics.errorRatePct || 0;
  const realErrorRate = parseFloat(measuredData.measuredErrorRatePct) || simErrorRate;

  const simRps = simulatedMetrics.throughputRps || simulatedMetrics.workloadRps || 1000;
  const realRps = parseFloat(measuredData.measuredRps) || simRps;

  // Calculate percentage accuracy delta
  const latencyError = Math.abs(simLatency - realLatency) / (realLatency || 1);
  const errorRateDiff = Math.abs(simErrorRate - realErrorRate);
  const rpsError = Math.abs(simRps - realRps) / (realRps || 1);

  const avgErrorFraction = (latencyError + (errorRateDiff / 100) + rpsError) / 3;
  const accuracyPct = Math.max(0, Math.min(100, Math.round((1 - avgErrorFraction) * 100)));

  let rating = 'Excellent';
  let badgeColor = 'text-emerald-700 bg-emerald-100 border-emerald-300';

  if (accuracyPct < 70) {
    rating = 'Needs Calibration';
    badgeColor = 'text-rose-700 bg-rose-100 border-rose-300';
  } else if (accuracyPct < 85) {
    rating = 'Good Match';
    badgeColor = 'text-amber-700 bg-amber-100 border-amber-300';
  }

  return {
    accuracyPct,
    rating,
    badgeColor,
    metrics: {
      simLatency,
      realLatency,
      latencyDeltaMs: Math.round(realLatency - simLatency),
      simErrorRate,
      realErrorRate,
      simRps,
      realRps,
    }
  };
}
